"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

    def set_left(self, node):
        self.left = node

    def set_right(self, node):
        self.right = node

def levelOrderTraversal(root):
    if (root is None):
        return []
    depth = [root]
    results = []
    loop = True
    while loop:
        level = []
        nextdepth = []
        index = 0
        innerloop = True
        while innerloop:
            try:
                node = depth[index]
                level.append(node.value)
                if (node.left is not None):
                    nextdepth.append(node.left)
                if (node.right is not None):
                    nextdepth.append(node.right)
                index = (index + 1)
            except Exception:
                innerloop = False
        results.append(level)
        depth = nextdepth
        if (len(depth) == 0):
            loop = False
    return results

root = Node(1)

root.set_left(Node(2))

root.set_right(Node(3))

root.left.set_left(Node(4))

root.left.set_right(Node(5))

print('Node Values Grouped by Depth')

index = 0

loop = True

while loop:
    try:
        level = levelOrderTraversal(root)[index]
        print(f'Level {index}: {level}')
        index = (index + 1)
    except Exception:
        loop = False
